### খ. অপটিমিস্টিক কার্ট আপডেট
ব্যবহারকারীর অভিজ্ঞতায় যাতে এক মুহূর্তের জন্যও কোনো ল্যাগ অনুভূত না হয়, সেজন্য কার্টে কিছু যোগ করার সাথে সাথে UI আপডেট হয়ে যায় এবং ব্রাউজার মেমোরিতে স্টেট ক্যাশ হয়ে যায়:

```javascript
// অপটিমিস্টিক কার্ট মিউটেশন লজিক
case 'ADD_TO_CART': {
  const existingIndex = state.items.findIndex(i => i.id === action.payload.id && i.size === action.payload.size);
  let updated;
  if (existingIndex > -1) {
    updated = [...state.items];
    updated[existingIndex].quantity += action.payload.quantity;
  } else {
    updated = [...state.items, action.payload];
  }
  localStorage.setItem('jv_cart', JSON.stringify(updated));
  return { ...state, items: updated };
}
